def build_biomechanics():
    """Retourne 215+ articles distincts de biomécanique, anatomie & sciences du sport."""
    entries = []
    seen = set()

    for title, subcat, summary, body, kw in BIOMECHANICS_PART_A + ANATOMY_ARTICLES + EXTENDED_SPORTS_SCIENCE:
        key = title.strip().lower()
        if key in seen:
            continue
        seen.add(key)
        meta = {"domaine": subcat, "mots_cles": kw}
        entries.append({
            "category": "biomecanique",
            "subcategory": subcat,
            "title": title,
            "summary": f"{subcat} — {summary}",
            "body": f"PRINCIPE CLÉ :\n{summary}\n\nANALYSE SCIENTIFIQUE & APPLICATION TERRAIN :\n{body}",
            "tags": f"biomecanique,science,{subcat.lower()},{kw}",
            "metadata_json": json.dumps(meta, ensure_ascii=False),
        })

